const statusClass=s=>/confirmed|available|active|approved|published|licensed|paid$|received|complete|returned|valid|accepted|resolved|enabled/i.test(s)&&!/unpaid|invalid/i.test(s)?'ok':/reject|expired|cancel|damaged|revoked|denied|failed/i.test(s)?'bad':/pending|hold|draft|review|outstanding|due|unpaid|grace/i.test(s)?'warn':'info';
