function readRoute(){let [m,p]=(location.hash.slice(1)||'venue/dashboard').split('/');mode=['venue','central','public'].includes(m)?m:'venue';page=p|| (mode==='public'?'home':'dashboard');tab=0;sideOpen=false;publicMenu=false;render();window.scrollTo(0,0)}
function switchbar(){return `<div class="prototypebar"><span>Interactive design prototype · Synthetic data</span><div class="switch">${[['public','Public website','home'],['venue','VenueDesk','dashboard'],['central','HAFZATECH Central','dashboard']].map(([m,l,p])=>`<button class="${mode===m?'active':''}" data-route="${m}/${p}">${l}</button>`).join('')}</div><span>No live operations</span></div>`}
function nav(groups){return groups.map(([g,items])=>`<div class="nav-group">${g}</div>${items.map(([p,label,i])=>`<button class="nav-link ${page===p?'active':''}" data-route="${mode}/${p}">${ic(i)}${esc(label)}</button>`).join('')}`).join('')}
function table(key,cols,items,actions=['View'],filter=true){const rowData=rows(key,items);return `${filter?`<div class="filterbar"><label class="field">Search records<input type="search" aria-label="Search records" data-filter="${key}" placeholder="Search names, references…"></label><label class="field">Status<select data-status-filter="${key}"><option value="">All statuses</option>${[...new Set(rowData.map(r=>r.at(-1)))].filter(s=>typeof s==='string'&&s.length<36).map(s=>`<option>${esc(s)}</option>`).join('')}</select></label>${btn('Export','export:'+key,'outline','audit')}</div>`:''}<div class="table-wrap"><table data-table="${key}"><thead><tr>${cols.map((c,i)=>`<th><button data-sort="${key}:${i}">${esc(c)} ↕</button></th>`).join('')}<th>Actions</th></tr></thead><tbody>${rowData.map((r,i)=>`<tr>${r.map((cell,j)=>`<td>${/status|result|mfa/i.test(cols[j]||'')?badge(cell):esc(cell)}</td>`).join('')}<td><div class="actions">${actions.map(a=>`<button class="btn sm ${a==='Reject'||a==='Cancel'||a==='Revoke'?'danger':'outline'}" data-record="${key}:${i}:${esc(a)}">${esc(a)}</button>`).join('')}</div></td></tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">No records in this view.</td></tr>`}</tbody></table></div><div class="pagination"><span data-count="${key}">${rowData.length} records · Page 1 of 1</span><span>Showing all matching records</span></div>`}
let tableConfigs={};
function registerTable(key,config){tableConfigs[key]=config;return table(key,config.cols,config.rows,config.actions,config.filter!==false)}
function generic(config,key){return pagehead(config.title,config.desc,config.cta?btn(config.cta,'new:'+key,'gold','plus'):'')+(config.stats?.length?metrics(config.stats):'')+card(config.title,registerTable(key,config),'',config.icon)}
function quick(items){return `<div class="quickgrid">${items.map(([l,p,i])=>`<button class="quick" data-route="${mode}/${p}">${ic(i)}<span>${esc(l)}</span><span class="caret">›</span></button>`).join('')}</div>`}
function availability(){return `<div class="fields" style="margin-bottom:14px">${field('Hall','hall','select','All halls',['All halls',...halls])}${field('Date','date','date','2027-11-20')}</div><div class="table-wrap"><table><thead><tr><th>Hall</th><th>Morning</th><th>Noon</th><th>Evening</th></tr></thead><tbody>${halls.map((h,i)=>`<tr><td>${h}</td>${['Available',i?'Available':'On hold','Booked'].map(s=>`<td>${badge(s)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function dashboard(){if(mode==='central')return pagehead('Central Control Center','Manage your customers, licensing and business operations.',btn('Add customer','new:central-customers','gold','plus'))+metrics([['Customers','2','users'],['Active installations','1','globe'],['Licensed','1','key'],['Outstanding billing','PKR 90,000','wallet']])+`<div class="grid2">${card('Customer directory',registerTable('central-customers',centralDefs.customers),btn('All customers','go:customers','outline sm'),'users')}${card('Quick actions',quick([['Customers','customers','users'],['Prepare renewal','licenseQueue','key'],['Review evidence','paymentEvidence','shield'],['Plans & pricing','plans','box'],['Support','support','message'],['Staff access','staff','users']]),'','plus')}</div><div class="grid2">${card('License health',registerTable('central-licenses',centralDefs.licenses),'','key')}${card('Recent activity','<div class="timeline"><div><b>License renewal prepared</b><br><small>Zargul Silver Marquee · revision 8</small></div><div><b>Payment evidence received</b><br><small>HC-INV-001 · Pending review</small></div><div><b>Support request opened</b><br><small>License verification question</small></div></div>','','audit')}</div>`;
return pagehead('Business Overview','Your venue at a glance.',btn('+ New booking','go:newBooking','gold'))+metrics([['Upcoming events','12','calendar'],['Available programs','8','box'],['Pending approvals','3','shield'],['Outstanding payments','PKR 132,500','wallet']])+`<div class="grid2">${card('Today’s program availability',availability(),btn('View calendar','go:calendar','outline sm'),'calendar')}${card('Quick actions',quick([['Check availability','calendar','calendar'],['Create booking','newBooking','plus'],['Find invoice','finance','wallet'],['Review approvals','approvals','shield'],['Manage inventory','inventory','box'],['Website editor','website','globe']]),'','plus')}</div><div class="grid2">${card('Recent bookings',registerTable('venue-reservations',{...venueDefs.reservations,filter:false,actions:['View']}),btn('All bookings','go:reservations','outline sm'),'book')}${card('Pending approvals',rows('venue-approvals',initial.approvals).filter(r=>r[4]==='Pending').map((r,i)=>`<div class="record"><div><b>${esc(r[1])}</b><small>${esc(r[2])} · ${esc(r[3])}</small></div>${btn('Review','go:approvals','gold sm')}</div>`).join('')||'<div class="empty">Nothing pending</div>','','shield')}</div>`}
function calendar(){return pagehead('Hall Calendar','Availability, holds and confirmed events by hall and program.',btn('New booking','go:newBooking','gold','plus'))+metrics([['Available programs','21','calendar'],['On hold','2','clock'],['Confirmed slots','4','check'],['Cleanup required','1','settings']])+card('Calendar controls',`<div class="fields three">${field('Hall','hall','select','All halls',['All halls',...halls])}${field('Date','date','date','2027-11-20')}${field('View','view','select','Week',['Day','Week','Month'])}</div><div class="actions" style="margin-top:12px">${btn('‹ Previous','cal:prev','outline')}${btn('Today','cal:today','outline')}${btn('Next ›','cal:next','outline')}${btn('Refresh','notice:Calendar refreshed','primary')}</div>`)+card('Weekly availability',`<div class="table-wrap"><table><thead><tr><th>Event date</th><th>Hall</th><th>Morning</th><th>Noon</th><th>Evening</th></tr></thead><tbody>${Array.from({length:7},(_,i)=>halls.map((h,j)=>`<tr><td>${20+i} Nov 2027</td><td>${h}</td>${[0,1,2].map(k=>`<td><button class="btn sm outline" data-action="slot:${20+i}:${j}:${k}">${badge((i+j+k)%5===0?'Booked':(i+j+k)%7===0?'On hold':'Available')}</button></td>`).join('')}</tr>`).join('')).join('')}</tbody></table></div><div class="note">Select an available program to start a new booking. Sample scheduling data only.</div>`,'','calendar')}
