function tabs(names){return `<div class="tabs">${names.map((n,i)=>`<button class="${i===tab?'active':''}" data-tab="${i}">${esc(n)}</button>`).join('')}</div>`}
function finance(){let c=financeConfigs[tab]||financeConfigs[0],key='finance-'+tab;return pagehead('Invoices & Payments','Manage invoices, receipts, authorized refunds and daily reconciliation.',btn(c.cta||'Export report',c.cta?'new:'+key:'export:'+key,'gold','plus'))+metrics([['Total invoiced','PKR 550,000','wallet'],['Collected','PKR 170,000','check'],['Outstanding','PKR 380,000','clock'],['Refunds','PKR 7,500','audit']])+card(c.title,tabs(financeTabs)+(tab===3?`<div class="fields" style="margin-bottom:15px">${field('UTC date','recon','date','2026-11-15')}${field('Account','account','select','All accounts',['All accounts','Cash on hand','Bank clearing'])}</div>`:'')+registerTable(key,c)+(tab===4?'<div class="note">The previous day has a documented physical cash variance. Historic closeouts are immutable.</div>':''),'','wallet')}
function inventory(){let c=inventoryConfigs[tab]||inventoryConfigs[0],key='inventory-'+tab;return pagehead('Hall Inventory','Purchase, receive, count, transfer and reconcile inventory.',btn(c.cta,'new:'+key,'gold','plus'))+metrics([['Catalog items','3','box'],['Owned usable','184','check'],['Owned damaged','7','shield'],['On loan','2','clock']])+card(c.title,`<div class="fields" style="margin-bottom:12px">${field('Operating company','company','select','Zargul Silver Marquee',['Zargul Silver Marquee'])}${field('Hall','hall','select','All halls',['All halls',...halls])}</div>`+tabs(inventoryTabs)+registerTable(key,c)+(tab===3?'<div class="note">Only a separately approved stock adjustment may post a movement. Counts alone never change inventory.</div>':''),'','box')}
function photos(){return pagehead('Hall photography','Manage the approved photography shown on the public site.',btn('Upload sample image','new:venue-photos','gold','plus'))+card('Hall media',`<div class="fields">${field('Hall','hall','select',halls[0],halls)}${field('Filter','status','select','Approved',['Approved','Draft','All'])}</div><div class="gallery-grid" style="margin-top:18px">${halls.map((h,i)=>`<article class="hall-card"><img src="hall.jpg" alt="Illustrative banquet venue"><div class="body"><h3>${h}</h3><p>${badge(i?'Draft':'Approved')} · Illustrative image</p><div class="actions">${btn('Use photo','notice:Sample photo selected','primary')}${btn('Remove','notice:Photo removal simulated','outline')}</div></div></article>`).join('')}</div><div class="note">Demo photography is illustrative, not photographs of the actual venue.</div>`)}
