function formFields(fs){return `<div class="fields">${fs.map((x,i)=>field(x.label,'v'+i,x.type,x.value,x.opts,x.full)).join('')}</div>`}
function setup(){return pagehead('Venue setup','Configure your venue in ten guided steps.','')+card('Installation wizard',`<div class="steps">${setupNames.map((s,i)=>`<button class="step ${i===setupStep?'active':i<setupStep?'done':''}" data-setup="${i}"><span class="num">${i<setupStep?'✓':i+1}</span>${s}</button>`).join('')}</div><div class="progress"><div style="width:${(setupStep+1)*10}%"></div></div><h2 style="margin-bottom:16px">${setupStep+1}. ${setupNames[setupStep]}</h2><form id="setup-form">${setupStep===9?`<div class="summary-lines">${setupNames.slice(0,9).map(s=>`<div><span>${s}</span>${badge('Complete')}</div>`).join('')}</div>`:formFields(setupFields[setupStep])}<div class="formfoot"><button type="button" class="btn outline" data-action="setup-back" ${setupStep===0?'disabled':''}>Back</button><button class="btn gold" type="submit">${setupStep===9?'Complete installation':'Save & continue →'}</button></div></form>`) }
function searchPage(){return pagehead('Universal search','Search people, invoices, bookings and inventory.')+card('Find a record',`<form id="universal-search"><div class="filterbar"><label class="field">Search<input type="search" name="term" placeholder="Ali, INV-000001, Gold Chair" required></label><button class="btn primary" type="submit">${ic('search')}Search</button></div></form><div id="search-results"><p class="muted">Enter a customer, invoice, booking or inventory keyword.</p></div>`)}
function login(){return `<div class="login-wrap"><section class="card login-card"><div class="brand"><i>✦</i>${mode==='central'?'HAFZATECH':'VenueDesk'}</div><h1 style="margin-top:20px;font-size:30px">Secure sign in</h1><p class="muted">Design demonstration. Do not enter real credentials.</p><form id="demo-login">${field('Email','email','email','demo@example.test')}${field('Password','password','password','mock-password')}${field('One-time code (demo)','otp','text','123456')}<button class="btn primary" style="width:100%" type="submit">Sign in to demo</button></form></section></div>`}
function bookingFlow(publicMode){let stages=['Event details','Choose hall','Review quote','Deposit','Confirmation'];let price=booking.hall===halls[0]?250000:150000,deposit=Math.round(price*.05);let body=bookingStep===0?`<div class="fields">${field('Event type','event','select',booking.event,['Wedding','Walima','Nikkah','Mehndi','Corporate'])}${field('Event date','date','date',booking.date)}${field('Program','program','select',booking.program,['Morning','Noon','Evening'])}${field('Expected guests','guest','number',booking.guest)}${field('Customer name','name','text',booking.name)}${field('Phone / WhatsApp','phone','tel',booking.phone)}</div>`:bookingStep===1?`<div class="hall-grid">${halls.map((h,i)=>`<button type="button" class="quick hall-card" style="display:block;padding:0;opacity:${Number(booking.guest)>(i?150:300)?'.5':'1'};border-color:${booking.hall===h?'#267b47':'#dfe5d9'}" data-hall="${i}" ${Number(booking.guest)>(i?150:300)?'disabled':''}><img src="hall.jpg" alt="Illustrative banquet hall" style="height:150px"><div class="body"><h3>${h}</h3><p>${i?150:300} guests · ${money(i?150000:250000)}</p>${badge(booking.hall===h?'Selected':'Available')}</div></button>`).join('')}</div>`:bookingStep===2?`<div class="summary-lines"><div><span>Event date</span><b>${esc(booking.date)}</b></div><div><span>Hall</span><b>${booking.hall}</b></div><div><span>Guests</span><b>${booking.guest}</b></div><div><span>Package</span><b>${money(price)}</b></div><div><span>Deposit (5%)</span><b>${money(deposit)}</b></div><div class="total"><span>Total quotation</span><b>${money(price)}</b></div></div><div class="note">This quote is a mock, not an actual booking offer.</div>`:bookingStep===3?`<div class="note">Synthetic deposit only. No payment is taken and no reservation exists outside this demonstration.</div><div class="fields">${field('Payment option','payment','select','Synthetic test payment',['Synthetic test payment'])}${field('Deposit amount','amount','text',money(deposit))}</div>`:`<div style="text-align:center;padding:35px 10px"><div style="font-size:55px;color:#227c48">✓</div><h1 style="font-size:32px">Mock booking confirmed</h1><p style="margin:12px 0">${booking.hall} · ${booking.date} · ${booking.program}</p>${badge('Confirmed')}<p style="margin:14px 0">Reference: DEMO-BK-0004</p>${btn('View booking status','route:public/status','primary')}</div>`;return `<div class="${publicMode?'bookwrap':''}">${publicMode?'<div class="eyebrow">Plan your celebration</div><h1 style="margin:8px 0 20px">Book your event</h1>':pagehead('New Booking / Quotation','Create a reservation through the guided workflow.')}<div class="steps">${stages.map((s,i)=>`<button class="step ${i===bookingStep?'active':i<bookingStep?'done':''}" data-book-step="${i}"><span class="num">${i<bookingStep?'✓':i+1}</span>${s}</button>`).join('')}</div><div class="booking-card">${card(stages[bookingStep],`<form id="booking-form">${body}${bookingStep<4?`<div class="formfoot"><button type="button" class="btn outline" data-action="book-back" ${bookingStep===0?'disabled':''}>Back</button><button class="btn gold" type="submit">${bookingStep===3?'Confirm synthetic deposit':'Continue →'}</button></div>`:''}</form>`)}${card('Booking summary',`<div class="summary-lines"><div><span>Hall</span><b>${booking.hall}</b></div><div><span>Date</span><b>${esc(booking.date)}</b></div><div><span>Program</span><b>${booking.program}</b></div><div><span>Guests</span><b>${booking.guest}</b></div><div><span>Package total</span><b>${money(price)}</b></div><div class="total"><span>Deposit due</span><b>${money(deposit)}</b></div></div><p class="muted" style="margin-top:15px">Prices and records shown are illustrative.</p>`,'','calendar')}</div></div>`}
function hallCards(){return `<div class="hall-grid">${halls.map((h,i)=>`<article class="hall-card"><img src="hall.jpg" alt="Illustrative wedding hall ${i+1}" style="object-position:${i?'right':'center'}"><div class="body"><div class="eyebrow">${i?'Intimate celebrations':'Signature venue'}</div><h2>${h}</h2><p>Up to ${i?150:300} guests · Weddings, Walima & receptions</p><div class="actions">${btn('View hall','route:public/hall'+i,'outline')}${btn('Check availability','public-book:'+i,'gold')}</div></div></article>`).join('')}</div>`}
const publicSection=(eyebrow,title,desc,body)=>`<section class="pubsection"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p>${body}</section>`;
const packageCards=()=>`<div class="cards">${[['Nikkah & intimate gatherings','A memorable ceremony with flexible seating and thoughtful details.'],['Walima & wedding receptions','Elegant celebrations with catering and service options.'],['Mehndi & festive events','Bring your celebration to life with music, lighting and decor.']].map(([t,d],i)=>`<article class="card"><div class="eyebrow">0${i+1} · Package</div><h2>${t}</h2><p style="margin:10px 0 20px" class="muted">${d}</p>${btn('Enquire','route:public/contact','outline')}</article>`).join('')}</div>`;
function serviceCards(){return `<div class="cards">${[['Stage & decoration','image'],['Music & sound','message'],['Fancy lighting','settings'],['Special entrances','arrow'],['Additional seating','users'],['Catering options','box']].map(([l,i])=>`<article class="card" style="text-align:center"><div style="color:#b28a37">${ic(i)}</div><h3 style="margin-top:8px">${l}</h3><p class="muted" style="margin:8px 0">Custom options for your occasion.</p></article>`).join('')}</div>`}
function enquiry(){return `<form class="card" id="enquiry-form"><h2 style="margin-bottom:14px">Check your date</h2><div class="fields">${field('Your name','name','text','')}${field('Phone / WhatsApp','phone','tel','')}${field('Email','email','email','')}${field('Event date','date','date','2027-12-01')}${field('Expected guests','guest','number',120)}${field('Preferred hall','hall','select',halls[0],halls)}${field('Event details','message','textarea','Tell us about your celebration',[],true)}</div><button class="btn gold" style="margin-top:18px" type="submit">Submit mock enquiry</button></form>`}
function publicPage(){switch(page){case'home':return `<section class="publichero"><div class="inner"><div class="eyebrow">Your moment, beautifully celebrated</div><h1>Where your most beautiful memories begin.</h1><p>Timeless spaces for weddings, Nikkah, Walima and celebrations worth remembering.</p><div class="actions">${btn('Plan your event ↗','route:public/booking','gold')}${btn('Explore our halls','route:public/halls','outline')}</div></div></section><section class="pubsection center"><div class="eyebrow">Welcome to Zargul Silver Marquee</div><h1>A beautiful setting for every celebration.</h1><p>Discover elegant spaces, flexible packages and thoughtful service from beginning to end.</p><div class="cards">${['Elegant spaces','Flexible packages','Dedicated team'].map((s,i)=>`<div class="card"><div class="eyebrow">0${i+1}</div><h3>${s}</h3></div>`).join('')}</div></section>${publicSection('Discover our spaces','Find your perfect setting','Explore our two distinctive banquet halls.',hallCards())}${publicSection('Make it yours','Celebrations for every occasion','Choose a package to suit your special day.',packageCards())}${publicSection('A personal touch','Everything your event needs','Thoughtful services and flexible choices.',serviceCards())}${publicSection('Start your story','Let’s plan something unforgettable.','Tell us the date and celebration you are planning.',enquiry())}`;case'halls':return publicSection('Our spaces','Explore our halls','Find the perfect setting for your event.',hallCards());case'hall0':case'hall1':{let i=page.endsWith('1')?1:0;return publicSection('Exclusive venue',halls[i],`Capacity: ${i?150:300} guests · Sample photography.`,`<img src="hall.jpg" alt="Illustrative hall" style="width:100%;max-height:450px;object-fit:cover;border-radius:12px"><div class="grid-even" style="margin-top:20px">${card('Venue details',`<p>Capacity: ${i?150:300} guests</p><p>Morning · Noon · Evening programs</p><p>Configurable packages, seating and decor.</p>`)}${card('Plan your event',availability()+btn('Book this hall','public-book:'+i,'gold'))}</div>`)}case'packages':return publicSection('Flexible event packages','Celebrations for every occasion','Choose the right package, with optional services.',packageCards());case'services':return publicSection('Tailored service','Everything your event needs','Explore available event options.',serviceCards());case'gallery':return publicSection('Inspiration','Moments made beautiful','Illustrative images only. Actual venue photography must replace these samples.',`<div class="gallery-grid">${Array.from({length:4},()=>'<img src="hall.jpg" alt="Illustrative celebration setting">').join('')}</div>`);case'about':return publicSection('Our story','Celebrate with elegance','A venue experience built around your special day.',`<div class="grid-even"><img src="hall.jpg" alt="Illustrative hall" style="width:100%;border-radius:12px">${card('Zargul Silver Marquee','<p>Two configurable halls for celebrations, with flexible programs and event packages. This prototype illustrates the venue’s intended public experience.</p>')}</div>`);case'contact':return publicSection('Get in touch','Let’s plan your event','Enquiries are simulated and never sent to a live venue.',enquiry());case'booking':return bookingFlow(true);case'status':return publicSection('Booking status','Check your reservation','Review a sample booking reference.',card('Booking lookup',`<form id="status-form"><div class="fields">${field('Booking reference','reference','text','DEMO-BK-0004')}${field('Customer phone','phone','tel','0300 1234567')}</div><button type="submit" class="btn primary" style="margin-top:15px">Check status</button></form><div id="status-result" style="margin-top:15px"></div>`));case'cancelled':return publicSection('Booking status','Mock booking cancelled','This is a simulated cancellation only.',btn('Plan another event','route:public/booking','gold'));case'privacy':return publicSection('Privacy','Privacy policy','Demonstration policy page.',card('Your information','<p>This prototype uses fictional records and browser-local state. It does not collect or transmit customer personal information.</p>'));case'terms':return publicSection('Terms','Booking terms','Demonstration terms, not a binding agreement.',card('Booking policy','<p>Pricing, availability, payment, cancellation and refund conditions are illustrative and require approved production terms.</p>'));default:return publicSection('Zargul Silver Marquee','Page not found','Return to the home page.',btn('Home','route:public/home','primary'))}}
function render(){tableConfigs={};let app=$('#app');if(mode==='public'){app.innerHTML=switchbar()+`<div class="public"><header class="publichead"><div class="public-brand"><div class="brandmark">✦</div><div>ZARGUL SILVER MARQUEE<small>WEDDINGS & CELEBRATIONS</small></div></div><button aria-label="Menu" class="iconbtn mobile-menu-btn" data-action="public-menu">${ic('menu')}</button><nav class="publicnav ${publicMenu?'open':''}">${navPublic.slice(0,7).map(([p,l])=>`<button class="${page===p?'active':''}" data-route="public/${p}">${l}</button>`).join('')}</nav>${btn('Check availability','route:public/booking','gold')}</header><div class="notice-banner">Design prototype · Illustrative imagery and sample data only</div>${publicPage()}<footer class="pubfoot"><div><h3>Zargul Silver Marquee</h3><p>Weddings & celebrations · A professional venue website design prototype. No actual payments or bookings.</p><p style="margin-top:18px">Designed by HAFZATECH · Sample attribution</p></div><div><h3>Explore</h3>${navPublic.slice(0,7).map(([p,l])=>`<button data-route="public/${p}">${l}</button>`).join('')}</div><div><h3>Booking & information</h3>${navPublic.slice(7).map(([p,l])=>`<button data-route="public/${p}">${l}</button>`).join('')}<button data-route="venue/dashboard">VenueDesk preview</button></div></footer></div>`;return}
let groups=mode==='central'?navCentral:navVenue,defs=mode==='central'?centralDefs:venueDefs,title=mode==='central'?'HAFZATECH':'VenueDesk',body='';if(page==='dashboard'){body=dashboard()}else if(page==='login'){body=login()}else if(mode==='venue'&&({calendar,finance,inventory,photos,website,licensing,setup,search:searchPage,newBooking:()=>bookingFlow(false)})[page]){body=({calendar,finance,inventory,photos,website,licensing,setup,search:searchPage,newBooking:()=>bookingFlow(false)})[page]()}else if(defs[page]){body=generic(defs[page],mode+'-'+page)}else body=pagehead('Page not found','Choose another page.',btn('Dashboard','go:dashboard','primary'));app.innerHTML=switchbar()+`<div class="layout"><aside class="sidebar ${sideOpen?'open':''}"><div class="brand"><i>✦</i>${title}</div><div class="brand-sub">${mode==='central'?'CENTRAL CONTROL CENTER':'ZARGUL SILVER MARQUEE'}</div>${nav(groups)}</aside><div class="work"><header class="topbar"><div class="actions"><button aria-label="Toggle navigation" class="iconbtn mobile-menu-btn" data-action="side-menu">${ic('menu')}</button><span class="topbrand">${title}</span></div><form class="topsearch" id="top-search">${ic('search')}<input name="term" type="search" placeholder="${mode==='central'?'Search customers or licenses':'Customer, booking or invoice ID'}" required></form><div class="topright"><button class="iconbtn" aria-label="Notifications" data-action="notifications">${ic('bell')}</button><span class="avatar">${mode==='central'?'HC':'OA'}</span><span class="role-label">${mode==='central'?'Administrator':'Owner / Admin'}</span></div></header><main class="content">${body}</main></div></div><nav class="mobilebar">${(mode==='venue'?[['dashboard','Home','home'],['calendar','Calendar','calendar'],['newBooking','Book','plus'],['finance','Finance','wallet'],['inventory','Inventory','box']]:[['dashboard','Home','home'],['customers','Customers','users'],['licenses','Licenses','key'],['billing','Billing','wallet'],['support','Support','message']]).map(([p,l,i])=>`<button class="${page===p?'active':''}" data-route="${mode}/${p}">${ic(i)}${l}</button>`).join('')}</nav>`;}
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3200)}
function dialog(title,body,footer='',callback){let d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close-dialog" aria-label="Close">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-actions">${footer}</div>`:''}`;d.showModal();d._callback=callback;}
function configFor(key){if(tableConfigs[key])return tableConfigs[key];if(key==='venue-photos')return def('Upload photo','','image',[],[],[f('Photo name'),f('Hall','select',halls[0],halls),f('Alt text')],'Upload');let [m,p]=key.split('-');return m==='central'?centralDefs[p]:m==='venue'?venueDefs[p]:m==='finance'?financeConfigs[Number(p)]:m==='inventory'?inventoryConfigs[Number(p)]:undefined}
function newRecord(key,index){let c=configFor(key);if(!c||!c.fields?.length){toast('This is a read-only mock view.');return}let fs=c.fields.map((x,i)=>({...x,value:index!==undefined&&rows(key,c.rows)[index]?.[i]!==undefined?rows(key,c.rows)[index][i]:x.value}));dialog(index===undefined?c.cta||'Create record':'Edit record',`<form id="record-form">${formFields(fs)}</form>`,btn('Cancel','close-dialog','outline')+btn('Save','submit-record','gold'),()=>{let fm=$('#record-form');if(!fm.reportValidity())return;let vals=[...new FormData(fm).values()].map(String);if(c.cols.length){let out=c.cols.map((label,i)=>vals[i]??(label==='Status'?'Pending':'—'));if(index===undefined)rows(key,c.rows).push(out);else rows(key,c.rows)[index]=out;save()}$('#dialog').close();render();toast('Saved to the interactive mock.')});}
function recordAction(key,i,action){let c=configFor(key);if(!c)return;let r=rows(key,c.rows)[i];if(!r)return;if(action==='Edit'){newRecord(key,i);return}if(action==='Download'){download(key,[c.cols,r]);return}if(action==='Workspace'){dialog('Customer workspace',`<div class="summary-lines">${r.map((v,j)=>`<div><span>${c.cols[j]}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="actions" style="margin-top:15px">${btn('Licenses','route:central/licenses','primary')}${btn('Billing','route:central/billing','outline')}${btn('Support','route:central/support','outline')}</div>`);return}if(action==='Link invoice'){dialog('Create linked mock invoice',`<p>Link ${esc(r[0])} to a reservation, invoice and deposit receipt in the mock.</p><div class="note">No real financial entry is posted.</div>`,btn('Cancel','close-dialog','outline')+btn('Confirm','confirm-record','gold'),()=>{rows('finance-0',initial.invoices).push(['INV-00000'+(rows('finance-0',initial.invoices).length+1),r[1],r.at(-1),'PKR 7,500','PKR 142,500','Outstanding']);save();$('#dialog').close();toast('Mock invoice linked.');render()});return}if(action==='View'){dialog(c.title+' · '+r[0],`<div class="summary-lines">${r.map((v,j)=>`<div><span>${esc(c.cols[j])}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="note">Illustrative record, not production data.</div>`,btn('Close','close-dialog','outline'));return}if(action==='Record payment'||action==='Refund'||action==='Prepare renewal'||action==='Review evidence'||action==='Convert'){let dest=action==='Record payment'?'finance-1':action==='Refund'?'finance-2':action==='Prepare renewal'?'central-licenseQueue':action==='Review evidence'?'central-paymentEvidence':'venue-proposals';newRecord(dest);return}let statusMap={'Approve':'Approved','Reject':'Rejected','Cancel':'Cancelled','Revoke':'Revoked','Submit':'Under review','Complete':'Complete','Check in':'In progress','Close event':'Complete','Receive':'Received','Review':'Reviewed','Dispatch':'Dispatched','Return':'Returned','Post adjustment':'Posted','Publish':'Published','Resolve':'Resolved','Restore':'Published','Verify':'Verified','Remove':'Removed','Reply':'Replied'};dialog(action+' · '+r[0],`<p>${esc(action)} this sample record?</p><div style="margin-top:15px">${field('Reason / note','reason','textarea','Mock operation review',[],true)}</div><div class="note">This only changes the prototype. Server authorization, immutable audit and release gates are not simulated as real security.</div>`,btn('Cancel','close-dialog','outline')+btn(action,'confirm-record','gold'),()=>{let si=c.cols.findIndex(x=>/status|result/i.test(x));if(si>=0)r[si]=statusMap[action]||action;else r[r.length-1]=statusMap[action]||action;save();$('#dialog').close();render();toast('Mock '+action.toLowerCase()+' saved.')})}
function download(key,arr){let c=configFor(key),lines=arr||[c?.cols||[],...(c?rows(key,c.rows):[])];let csv=lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=key+'-sample.csv';a.click();URL.revokeObjectURL(a.href);toast('Demo CSV exported.')}
function action(s){let [a,...rest]=s.split(':'),v=rest.join(':');if(a==='go'){route(mode,v)}else if(a==='route'){if($('#dialog').open)$('#dialog').close();location.hash=v}else if(a==='new')newRecord(v);else if(a==='export')download(v);else if(a==='notice')toast(v);else if(a==='close-dialog')$('#dialog').close();else if(a==='submit-record'||a==='confirm-record')$('#dialog')._callback?.();else if(a==='side-menu'){sideOpen=!sideOpen;$('.sidebar')?.classList.toggle('open',sideOpen)}else if(a==='public-menu'){publicMenu=!publicMenu;$('.publicnav')?.classList.toggle('open',publicMenu)}else if(a==='book-back'){bookingStep=Math.max(0,bookingStep-1);render()}else if(a==='setup-back'){setupStep=Math.max(0,setupStep-1);render()}else if(a==='public-book'){booking.hall=halls[Number(v)];bookingStep=0;route('public','booking')}else if(a==='slot'){let [date,h,p]=rest;booking.date='2027-11-'+date;booking.hall=halls[Number(h)];booking.program=['Morning','Noon','Evening'][Number(p)];bookingStep=0;route('venue','newBooking')}else if(a==='cal'){const input=$('input[name=date]');if(input){let d=new Date(input.value+'T12:00:00');if(v==='today')d=new Date();else d.setDate(d.getDate()+(v==='next'?7:-7));input.value=d.toISOString().slice(0,10)}toast('Calendar date updated in mock.')}else if(a==='save-editor'){data.editorTitle=$('input[name=editorTitle]')?.value||'';save();render();toast('Draft saved in mock.')}else if(a==='preview'){let x=$('#editor-preview');if(x){x.style.maxWidth=v+'%';x.style.margin='auto'}}else if(a==='license-state'){let s=$('select[name=state]').value;$('#license-note').textContent=`Simulated state: ${s}. No actual entitlement changed.`;toast(s==='Expired'?'Mock access restricted':'License state simulated.')}else if(a==='notifications'){dialog('Notifications','<div class="record"><div><b>Pending approval</b><small>Stocktake variance awaiting review</small></div></div><div class="record"><div><b>License reminder</b><small>Next verification in 15 days</small></div></div>',btn('Close','close-dialog','outline'))}}
function filter(key){let term=($(`[data-filter="${key}"]`)?.value||'').toLowerCase(),status=$(`[data-status-filter="${key}"]`)?.value||'',trs=$$(`[data-table="${key}"] tbody tr`);let visible=0;trs.forEach(tr=>{let text=tr.textContent.toLowerCase();let show=text.includes(term)&&(!status||text.includes(status.toLowerCase()));tr.hidden=!show;if(show)visible++});let x=$(`[data-count="${key}"]`);if(x)x.textContent=visible+' matching records'}
function searchResults(term){let all=[...rows('venue-reservations',initial.bookings),...rows('finance-0',initial.invoices),...rows('inventory-0',initial.stock),...rows('central-customers',initial.clients)].filter(r=>r.join(' ').toLowerCase().includes(term.toLowerCase()));return all.length?all.map(r=>`<div class="record"><div><b>${esc(r[0])}</b><small>${r.slice(1).map(esc).join(' · ')}</small></div>${badge('Match')}</div>`).join(''):'<div class="empty">No matching sample records.</div>'}
document.addEventListener('click',e=>{let el=e.target.closest('button,[data-route]');if(!el)return;if(el.dataset.route){e.preventDefault();if($('#dialog').open)$('#dialog').close();location.hash=el.dataset.route;return}if(el.dataset.action){if(el.type==='submit'&&!el.dataset.action)return;e.preventDefault();action(el.dataset.action);return}if(el.dataset.tab!==undefined){tab=+el.dataset.tab;render();return}if(el.dataset.record){let [k,i,...a]=el.dataset.record.split(':');recordAction(k,+i,a.join(':'));return}if(el.dataset.sort){let [k,i]=el.dataset.sort.split(':');let c=configFor(k);if(c){rows(k,c.rows).sort((a,b)=>String(a[+i]).localeCompare(String(b[+i])));render()}return}if(el.dataset.editor!==undefined){editorSection=+el.dataset.editor;render();return}if(el.dataset.hall!==undefined){booking.hall=halls[+el.dataset.hall];render();return}if(el.dataset.setup!==undefined&&+el.dataset.setup<=setupStep){setupStep=+el.dataset.setup;render();return}if(el.dataset.bookStep!==undefined&&+el.dataset.bookStep<=bookingStep){bookingStep=+el.dataset.bookStep;render()}});
document.addEventListener('input',e=>{if(e.target.dataset.filter)filter(e.target.dataset.filter);if(e.target.name==='editorTitle'){let h=$('#editable-title');if(h)h.textContent=e.target.value}});
document.addEventListener('change',e=>{if(e.target.dataset.statusFilter)filter(e.target.dataset.statusFilter)});
document.addEventListener('submit',e=>{let id=e.target.id;if(!id)return;e.preventDefault();let fd=Object.fromEntries(new FormData(e.target));if(id==='booking-form'){if(bookingStep===0){Object.assign(booking,fd);if(Number(booking.guest)>300){toast('Maximum mock hall capacity is 300.');return}}if(bookingStep<4){bookingStep++;if(bookingStep===4){let r=['DEMO-BK-'+Date.now().toString().slice(-4),booking.name,booking.date,booking.hall,booking.program,'Confirmed',money(booking.hall===halls[0]?250000:150000)];rows('venue-reservations',initial.bookings).push(r);save()}render();window.scrollTo(0,0)}}else if(id==='setup-form'){data['setup-'+setupStep]=fd;save();if(setupStep<9){setupStep++;render()}else toast('Mock installation completed.')}else if(id==='enquiry-form'){rows('venue-enquiries',initial.enquiries).push(['DEMO-ENQ-'+Date.now().toString().slice(-4),fd.name,fd.date,fd.guest,fd.hall,'New']);save();toast('Mock enquiry received. View it in VenueDesk.');e.target.reset()}else if(id==='status-form'){$('#status-result').innerHTML=`<div class="record"><div><b>${esc(fd.reference)}</b><small>${esc(booking.hall)} · ${booking.date}</small></div>${badge('Confirmed')}</div>${btn('Cancel mock booking','route:public/cancelled','danger')}`}else if(id==='universal-search')$('#search-results').innerHTML=searchResults(fd.term);else if(id==='top-search')dialog('Search results',searchResults(fd.term),btn('Close','close-dialog','outline'));else if(id==='demo-login'){toast('Mock authentication completed.');route(mode,'dashboard')}});
// Startup and first-run route protection are supplied by installer.js.
